        "task_id": 2,
        "difficulty": "High",
        "task_name": "[A brief task name]",
        "task_requirement": "[Insert 300+ word structured instructions]",
        "elevator_pitch_summary": "[Casual summary]",
        "deep_dive_summary": "[Technical casual summary]"
    }
]

